content.content:
    # MTD connector IDs and display names, used only to name connectors in the result.
    # Based on https://github.com/microsoft/Microsoft365DSC/blob/Dev/Modules/Microsoft365DSC/DscResources/MSFT_IntuneMobileThreatDefenseConnector/MSFT_IntuneMobileThreatDefenseConnector.psm1
    # Windows Security Center and Trellix differ from that file; both were checked against the IDs Graph returns in a tenant. iVerify is not in that file.
    $mtdConnectorInformation = @{
23:    It 'Passes for an enabled connector with a recent heartbeat' {
31:    It 'Explains <State> without changing it to a pass' -ForEach @(
46:    It 'Explains a missing heartbeat for <Heartbeat>' -ForEach @(
57:    It 'Reports both incomplete setup and a missing heartbeat' {
66:    It 'Explains a stale heartbeat' {
73:    It 'Preserves the existing heartbeat boundary at <Hours> hours' -ForEach @(
82:    It 'Fails when one of several connectors is unhealthy and reports both' {
97:    It 'Escapes unknown connector IDs and states in the report table' {
107:    It 'Keeps the no-connectors skip' {
116:    It 'Propagates Graph errors' {
134:    It 'Records incomplete setup as Failed with actionable result details' {
150:    It 'Records the no-connectors case as Skipped through the engine' {
158:    It 'Records unreadable connector data as Error through the engine' {
        $script:Connector.partnerState = $State

        Test-MtMobileThreatDefenseConnectors | Should -BeFalse
        $script:Result | Should -BeLike $Reason
    }

    It 'Explains a missing heartbeat for <Heartbeat>' -ForEach @(
        @{ Heartbeat = '0001-01-01T00:00:00Z' }
        @{ Heartbeat = $null }
    ) {
        $script:Connector.lastHeartbeatDateTime = $Heartbeat

        Test-MtMobileThreatDefenseConnectors | Should -BeFalse
        $script:Result | Should -BeLike '*Never received*'
        $script:Result | Should -Not -BeLike '*0001-01-01*'
    }

    It 'Reports both incomplete setup and a missing heartbeat' {
        $script:Connector.partnerState = 'notSetUp'
        $script:Connector.lastHeartbeatDateTime = '0001-01-01T00:00:00Z'

        Test-MtMobileThreatDefenseConnectors | Should -BeFalse
        $script:Result | Should -BeLike '*Setup is incomplete*'
        $script:Result | Should -BeLike '*No heartbeat has been received*'
    }

    It 'Explains a stale heartbeat' {
        $script:Connector.lastHeartbeatDateTime = '2026-11-05T12:00:00Z'

        Test-MtMobileThreatDefenseConnectors | Should -BeFalse
        $script:Result | Should -BeLike '*No heartbeat in the last 48 hours*'
    }

    It 'Preserves the existing heartbeat boundary at <Hours> hours' -ForEach @(
        @{ Hours = 47; Expected = $true }
        @{ Hours = 48; Expected = $false }
    ) {
        $script:Connector.lastHeartbeatDateTime = ([datetime]'2026-11-08T12:00:00Z').AddHours(-$Hours)

        Test-MtMobileThreatDefenseConnectors | Should -Be $Expected
    }

    It 'Fails when one of several connectors is unhealthy and reports both' {
        Mock -ModuleName Maester Invoke-MtGraphRequest {
            $script:Connector
            [pscustomobject]@{
